static void Log(const char* s) { strcat(g_log, s); strcat(g_log, " "); }

static void Model(const SInput& in)
{
    g_log[0] = 0;
    Log("spec"); Log("fog");
    bool composite = (in.type == 10);
    if (in.diffuse_index == 0)
