    if (!in.shaders_ok) { Log("restore"); Log("flush"); return; }
    shader_flags = in.shader_flags_out; degenerate = in.degenerate_out;
    if (!in.blocks_ok) { Log("restore"); Log("flush"); return; }
    Log("first"); Log("ccw"); Log("occprep");
