    R()->ButtonPulseTimer.Active = true; R()->ButtonPulseTimer.Opening = true; R()->ButtonPulseTimer.FadeInTime = 0.6f;
    R()->ButtonPulseTimer.FadeOutTime = 0.6f; R()->ButtonPulseTimer.OpenTimer = 0.15f;
    Texts(1, 2, 3);
