};
static Thing T(const char* def, float x, float y, float z, long map)
{ Thing t; t.Def = def; t.Pos = V3(x, y, z); t.Dead = false; t.Info = false; t.Map = map; t.Active = t.Owned = t.ForSale = t.Married = t.Attracted = false;
