        ok = ok && Is(m, n, "UI_MINI_MAP_MARKER", 0.0f, 0.0f) && m.Parent[n].Graphic == 7; ++n;
        ok = ok && Is(m, n++, "UI_HENCHMAN_MARKER", 4.0f, 200.0f) && n == m.Parent.size() && m.RegionExits == 1;
