        Model u; Base(u); u.Maps[1].Loaded = false; Cached c; c.Region = 4; c.Def = "UI_OLD"; c.Graphic = 0; c.Angle = 0; c.Length = 6; u.MiniMapMarkers.push_back(c);
        u.Create(region, &hero);
