    float customY = RoundToDecimals(customYUnit * 2.0f - 1.0f, 2);
    float customXUnit = GetUnitFloat(CustomDirectionX, 1.0f / 255.0f);
    float customX = RoundToDecimals(customXUnit * 2.0f - 1.0f, 2);
