    if (QuestFailed) {
        if (IsActiveThreadTerminating())
            return;
        if (Game->IsRegionLoaded("Fisherman")) {
            if (IsActiveThreadTerminating())
                return;
            while (!Game->MsgOnRegionLoaded(regionName) && !((Deputy1Escaped || Deputy1Killed) && AllGruntsKilled)) {
                Game->NewScriptFrame();
                if (IsActiveThreadTerminating())
                    return;
            }
            if (IsActiveThreadTerminating())
                return;
        }
        else if (Game->IsRegionLoaded("GreatwoodLake")) {
