                return;
            while (!Game->MsgOnRegionLoaded(regionName) && !((LeaderEscaped || LeaderKilled) && AllGruntsKilled)) {
                Game->NewScriptFrame();
                if (IsActiveThreadTerminating())
                    return;
            }
            if (IsActiveThreadTerminating())
                return;
        }
