                        C3DVector trailEnd;
                        if (trailLength > 2.0f) {
                            float trailScale = trailLength * 0.5f;
                            trailEnd = particle->GetRecordedPos(2.0f, interpolate);
                            trailEnd = (trailEnd - pos) * trailScale + pos;
                        } else
                            trailEnd = particle->GetRecordedPos(trailLength, interpolate);
