    if (clock.BankIndex) {
        CGraphicFrame frame;
        if (!NEngineInternal::GPResourceManager->PeekGraphicBank((EGraphicBankNo)0)->PeekGraphicInfoFrame(clock.BankIndex, clock.Frame)->GetFrame(frame, 0, flags))
            return;
