        uvs.V[0] = 0.0f;
        uvs.U[1] = 1.0f;
        uvs.V[1] = 0.0f;
        uvs.U[2] = 1.0f;
        uvs.V[2] = 1.0f;
        uvs.U[3] = 0.0f;
        uvs.V[3] = 1.0f;
