        uvs.V[0] += offset.Y;
        uvs.U[1] += offset.X;
        uvs.V[1] += offset.Y;
        uvs.U[2] += offset.X;
        uvs.V[2] += offset.Y;
        uvs.U[3] += offset.X;
        uvs.V[3] += offset.Y;
