            uvs.U[1] *= width;
            uvs.U[2] *= width;
            uvs.U[3] *= width;
            float height = (float)textures[0]->GetHeight(0);
            uvs.V[0] *= height;
            uvs.V[1] *= height;
            uvs.V[2] *= height;
            uvs.V[3] *= height;
        } else if (textures[1] && textures[1]->GetPixelFormat().IsLinear()) {
            float width = (float)textures[1]->GetWidth(0);
