    top_right.X *= scale_x;
    top_right.X -= 1.0f;
    top_right.Y *= scale_y;
    top_right.Y = 1.0f - top_right.Y;
    bottom_left.X *= scale_x;
    bottom_left.X -= 1.0f;
    bottom_left.Y *= scale_y;
    bottom_left.Y = 1.0f - bottom_left.Y;
    bottom_right.X *= scale_x;
    bottom_right.X -= 1.0f;
    bottom_right.Y *= scale_y;
    bottom_right.Y = 1.0f - bottom_right.Y;

