    float ys[6] = { cy, (float)c.tly, (float)c.tly, (float)c.bry, (float)c.bry, (float)c.tly };
    float us[6] = { 0.5f, 0.5f, 1.0f, 1.0f, 0.0f, 0.0f };
    float vs[6] = { 0.5f, 0.0f, 0.0f, 1.0f, 1.0f, 0.0f };
