                m.ForcedAttitude = 12;
                if (!m.HasBeenInLove) {
                    m.HasBeenInLove = true;
                    if (w.HeroAlive && w.HasStats) { ++w.Lovers; w.ScoreActivity = 0xb; w.ScoreValue = (float)w.Lovers; }
