            float attraction = m.Love / D.LoveThreshold;
            if (attraction > 1.0f) attraction = 1.0f;
            long alpha = 0xff;
            if (attraction == 1.0f) { alpha = (w.Frame * 4) % 0x1ff; if (alpha > 0xff) alpha = 0x1ff - alpha; }
