        m.FrameLastCulled = w.Frame;
        for (std::map<long, long>::iterator it = m.Gifts.begin(); it != m.Gifts.end();) {
            std::map<long, long>::iterator next = it; ++next;
            if (w.Frame - it->second > D.SecsRememberGifts * w.FPS) m.Gifts.erase(it);
