    corner0.X -= 1.0f;
    corner0.Y *= scale_y;
    corner0.Y = 1.0f - corner0.Y;
    corner1.X *= scale_x;
    corner1.X -= 1.0f;
    corner1.Y *= scale_y;
    corner1.Y = 1.0f - corner1.Y;
    corner2.X *= scale_x;
    corner2.X -= 1.0f;
    corner2.Y *= scale_y;
    corner2.Y = 1.0f - corner2.Y;
    corner3.X *= scale_x;
    corner3.X -= 1.0f;
    corner3.Y *= scale_y;
