    long fireball2 = CGameDefinitionManager::Get().GetDefGlobalIndexFromName("FIREBALL_JACK_OF_BLADES2");
    long fireball3 = CGameDefinitionManager::Get().GetDefGlobalIndexFromName("FIREBALL_JACK_OF_BLADES3");
