                if (boss->CountLivingHelpers() == 0)
                    Summon(familyIndex, false);
                if (!IsStillRunnable()) {
                    Terminate();
                    return;
                }
                CCharString animation("ST_IDLE", -1);
                AIAction_PerformActionAndWait(CCreatureAction_PlayCombatAnimation(GetCreature(), *PTargetThing.Get(), animation, true), true);
            }
            break;
        case 6: {
            CCharString animation("ST_IDLE", -1);
