        for (k = 0; k < 4; ++k) {
            int v;
            if (ramp) {
                int r = Sat16(row[k] >> 15);
                int m = (r * gain[k]) >> 16;
                v = m * 4;
            } else
                v = row[k] >> 14;
            out[4 * i + k] += v;
