        for (size_t s = 0; s < it->second->subs.size(); s++) { Vs[it->second->subs[s].first].pairs[it->second->subs[s].second] = (int)s; Vs[it->second->subs[s].second].pairs[it->second->subs[s].first] = (int)s; }
